"use client";

import { type MotionValue, motion, useTransform } from "motion/react";
import { type CSSProperties, useId } from "react";
import type { Picture } from "./pictures";
import { SeamFilter } from "./seam-filter";

// Cortexcn item "gallery-liquid-seams-01", revision 95e8a7e696e2, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-liquid-seams-01/95e8a7e696e2.json

interface SeamBandProps {
  /** The picture above the seam. */
  upper: Picture;
  /** The picture below the seam. */
  lower: Picture;
  flow: MotionValue<number>;
  strength: MotionValue<number>;
  /** The furthest, in pixels, the paint is pushed at full speed. */
  maxSmear: number;
  seed: number;
}

/** Below this strength the band is hidden and runs no filter at all. */
const AT_REST = 0.005;
/** How far the paint lags behind the scroll, as a share of the smear. */
const TRAIL_SHARE = 0.5;

/** Fades the band out at its top and bottom, into the crisp pictures. */
const EDGE_FADE =
  "linear-gradient(to bottom, transparent, black 24%, black 76%, transparent)";
/** Brings the lower picture in across the middle of the band. */
const CROSSFADE = "linear-gradient(to bottom, transparent 30%, black 70%)";

const UNSAFE_ID = /[^\w-]/g;

/**
 * One picture's edge as paint for the seam: the picture lined up with its
 * tile, and a mirrored copy past the edge, so the paint runs on into the gap
 * without a hard line. Both lag a little behind the scroll.
 */
function PaintedEdge({
  picture,
  edge,
  trail,
}: {
  picture: Picture;
  edge: "top" | "bottom";
  trail: MotionValue<number>;
}) {
  const shape = { aspectRatio: `${picture.width} / ${picture.height}` };
  // Where the picture's edge sits in the band, from the band's own edge.
  const lined: CSSProperties =
    edge === "bottom"
      ? { bottom: "calc(var(--seam-depth) + var(--seam-gap))" }
      : { top: "calc(var(--seam-depth) + var(--seam-gap))" };
  const mirrored: CSSProperties =
    edge === "bottom"
      ? { top: "var(--seam-depth)" }
      : { bottom: "var(--seam-depth)" };

  return (
    <motion.div className="absolute inset-0" style={{ y: trail }}>
      {/* biome-ignore lint/performance/noImgElement: framework-agnostic registry block */}
      <img
        alt=""
        className="absolute inset-x-0 h-auto w-full"
        decoding="async"
        draggable={false}
        height={picture.height}
        loading="lazy"
        src={picture.src}
        style={{ ...shape, ...lined }}
        width={picture.width}
      />
      {/* biome-ignore lint/performance/noImgElement: framework-agnostic registry block */}
      <img
        alt=""
        className="absolute inset-x-0 h-auto w-full -scale-y-100"
        decoding="async"
        draggable={false}
        height={picture.height}
        loading="lazy"
        src={picture.src}
        style={{ ...shape, ...mirrored }}
        width={picture.width}
      />
    </motion.div>
  );
}

/**
 * The join between two pictures. It reaches into both and spans the gap, and
 * only shows while the page scrolls fast: the lower picture fades in over the
 * upper one across the middle, and the seam filter swirls the two together.
 * As the scroll slows it fades out, and the crisp pictures and the gap
 * between them show through again. At rest it is hidden with no filter.
 */
export function SeamBand({
  upper,
  lower,
  flow,
  strength,
  maxSmear,
  seed,
}: SeamBandProps) {
  const filterId = `liquid-seam-${useId().replace(UNSAFE_ID, "")}`;
  const opacity = useTransform(strength, [0, 0.5], [0, 1]);
  const visibility = useTransform(strength, (value) =>
    value > AT_REST ? "visible" : "hidden",
  );
  const filter = useTransform(strength, (value) =>
    value > AT_REST ? `url(#${filterId})` : "none",
  );
  // feDisplacementMap moves a pixel by up to half its scale either way.
  const scale = useTransform(strength, (value) => value * maxSmear * 2);
  const trail = useTransform(flow, (value) => value * maxSmear * TRAIL_SHARE);

  return (
    <>
      <SeamFilter id={filterId} scale={scale} seed={seed} />
      <motion.div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 z-10 overflow-hidden"
        style={{
          top: "calc(100% - var(--seam-depth))",
          height: "calc(var(--seam-depth) * 2 + var(--seam-gap))",
          opacity,
          visibility,
          filter,
          maskImage: EDGE_FADE,
          WebkitMaskImage: EDGE_FADE,
        }}
      >
        <PaintedEdge edge="bottom" picture={upper} trail={trail} />
        {/* The mask stays put while the paint inside it trails. */}
        <div
          className="absolute inset-0"
          style={{ maskImage: CROSSFADE, WebkitMaskImage: CROSSFADE }}
        >
          <PaintedEdge edge="top" picture={lower} trail={trail} />
        </div>
      </motion.div>
    </>
  );
}

"use client";

import { type MotionValue, useMotionValueEvent } from "motion/react";
import { useRef } from "react";

// Cortexcn item "gallery-liquid-seams-01", revision 95e8a7e696e2, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-liquid-seams-01/95e8a7e696e2.json

interface SeamFilterProps {
  id: string;
  /** Seeds the noise, so no two seams swirl the same way. */
  seed: number;
  /** How hard the noise pushes the paint, in pixels. Follows the scroll. */
  scale: MotionValue<number>;
}

/**
 * Soft noise, wide from side to side and tight from top to bottom. The green
 * channel is pushed toward its extremes and the red one is flattened, so the
 * paint runs up and down in wavy streaks and barely drifts sideways.
 */
const NOISE_TO_FLOW = [
  "0.4 0 0 0 0.3",
  "0 1.8 0 0 -0.4",
  "0 0 1 0 0",
  "0 0 0 0 1",
].join(" ");

/**
 * The SVG filter that marbles one seam. It moves every pixel of the seam band
 * up or down by an amount read from the noise, so the two pictures run into
 * each other in streaks. The push is set straight on the element as the
 * scroll speed changes, so it never re-renders React.
 */
export function SeamFilter({ id, seed, scale }: SeamFilterProps) {
  const mapRef = useRef<SVGFEDisplacementMapElement>(null);

  useMotionValueEvent(scale, "change", (value) => {
    mapRef.current?.setAttribute("scale", value.toFixed(2));
  });

  return (
    <svg
      aria-hidden="true"
      className="pointer-events-none absolute size-0 overflow-hidden"
      focusable="false"
    >
      <filter
        colorInterpolationFilters="sRGB"
        height="140%"
        id={id}
        width="120%"
        x="-10%"
        y="-20%"
      >
        <feTurbulence
          baseFrequency="0.008 0.03"
          numOctaves={2}
          result="noise"
          seed={seed}
          type="fractalNoise"
        />
        <feColorMatrix
          in="noise"
          result="flow"
          type="matrix"
          values={NOISE_TO_FLOW}
        />
        <feDisplacementMap
          in="SourceGraphic"
          in2="flow"
          ref={mapRef}
          scale={0}
          xChannelSelector="R"
          yChannelSelector="G"
        />
      </filter>
    </svg>
  );
}

"use client";

import {
  type MotionValue,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  useVelocity,
} from "motion/react";
import { type RefObject, useEffect } from "react";

// Cortexcn item "gallery-liquid-seams-01", revision 95e8a7e696e2, MIT license.
// https://ui.cortexcn.dev/r/v/gallery-liquid-seams-01/95e8a7e696e2.json

export interface SeamFlow {
  /**
   * From -1 to 1: positive while the page scrolls down, negative while it
   * scrolls up, and 0 when it is still.
   */
  flow: MotionValue<number>;
  /** How far the seams have melted, from 0 when still to 1 at full speed. */
  strength: MotionValue<number>;
}

/** Scrolling slower than this share of the full speed leaves the seams alone. */
const CALM_SHARE = 0.25;
/** A pause longer than this, in milliseconds, means the next scroll is new. */
const IDLE_MS = 120;
/** Picks up quickly and settles in about half a second, without a bounce. */
const SETTLE = { stiffness: 170, damping: 28, mass: 0.7 };

/**
 * Turns the gallery's speed on screen into how far its seams melt. It reads
 * the gallery's own position on every scroll, so it works whether the window
 * scrolls or a box around the gallery does. With reduced motion it never
 * listens, and the seams stay crisp.
 */
export function useSeamFlow(
  target: RefObject<HTMLElement | null>,
  fullSpeed: number,
): SeamFlow {
  const reduceMotion = useReducedMotion();
  /** How far the gallery has moved up the screen, in pixels. */
  const travel = useMotionValue(0);
  const speed = useVelocity(travel);
  const calm = fullSpeed * CALM_SHARE;
  const push = useTransform(
    speed,
    [-fullSpeed, -calm, calm, fullSpeed],
    [-1, 0, 0, 1],
  );
  const flow = useSpring(push, SETTLE);
  const strength = useTransform(flow, (value) => Math.min(Math.abs(value), 1));

  useEffect(() => {
    const node = target.current;
    if (!node || reduceMotion) {
      return;
    }
    let lastAt = Number.NEGATIVE_INFINITY;
    const measure = () => {
      const now = performance.now();
      const moved = -node.getBoundingClientRect().top;
      // The first reading of a new scroll only marks where it starts, so a
      // layout change made while the page was still never counts as speed.
      if (now - lastAt > IDLE_MS) {
        travel.jump(moved);
      } else {
        travel.set(moved);
      }
      lastAt = now;
    };
    // Scroll events do not bubble, so listening while they travel down to
    // the target catches the window and every scrolling box alike.
    const options = { capture: true, passive: true };
    document.addEventListener("scroll", measure, options);
    return () => document.removeEventListener("scroll", measure, options);
  }, [target, reduceMotion, travel]);

  return { flow, strength };
}
